//! Actual finite Kind11 read consumers in the SAME query/source family.
use super::*;use super::super::super::generator_policy::GeneratorName;
const READ_CODE:&str="#if 0\nCAPABILITIES(/datum/probe)\n    when(PROC_REF(check))\n#endif\n/datum/act/eval\n/datum/probe\n    var/value\n    var/derived\n    proc/check(datum/act/eval/A)\n        return derived\n    proc/derive_derived()\n        return value\n    proc/draw()\n        return value\n";
#[test]fn actual_reads_generator_kind11_uses_original_read_children_and_warm_artifact_without_io(){
 let fixture=Fixture::new(READ_CODE,false);let capture=fixture.capture();let before=fixture.reads.load(Ordering::Relaxed);let stop=fixture.db.fail_body_syntax_after_for_test(0,io::Error::from_raw_os_error(1450));let failure=fixture.db.with_generator_fixture(&capture,GeneratorName::Reads,|_|->io::Result<()>{panic!("actual original body IO must precede completed Reads artifact")}).unwrap_err();assert_eq!(failure.raw_os_error(),Some(1450));assert_eq!(fixture.db.db.stats(dm_query::Kind(11)).computed,0);drop(stop);
 let(pointer,text)=fixture.db.with_generator_fixture(&capture,GeneratorName::Reads,|artifact|{assert_eq!(artifact.path(),"code/engine/_generated/reads.dm");assert!(artifact.diagnostics().is_empty());assert!(artifact.text().contains("/datum/probe::check"));assert!(artifact.text().contains("generated_reads_table"));Ok((artifact.text().as_ptr()as usize,artifact.text().to_owned()))}).unwrap();let computed=fixture.db.db.stats(dm_query::Kind(11)).computed;let read_computed=fixture.db.db.stats(REACTIVE_RESULT).computed;assert!(read_computed>=2,"handler and actual derive reads are original Kind12 children");let bodies=fixture.db.db.stats(crate::query_db::body_syntax::BODY_SYNTAX).computed;assert!(bodies>=2);fixture.db.with_generator_fixture(&capture,GeneratorName::Reads,|artifact|{assert_eq!(artifact.text().as_ptr()as usize,pointer);assert_eq!(artifact.text(),text);Ok(())}).unwrap();assert_eq!(fixture.db.db.stats(dm_query::Kind(11)).computed,computed);assert_eq!(fixture.db.db.stats(REACTIVE_RESULT).computed,read_computed);assert_eq!(fixture.reads.load(Ordering::Relaxed),before,"cold and warm renderer use original captured sources only");
 let token=crate::daemon::control::Cancellation::default();let guard=crate::daemon::control::bind_with_deadline(token.clone(),Instant::now()+Duration::from_secs(30));token.cancel();assert_eq!(fixture.db.with_generator_fixture(&capture,GeneratorName::Reads,|_|Ok(())).unwrap_err().kind(),io::ErrorKind::Interrupted);drop(guard);fixture.db.with_generator_fixture(&capture,GeneratorName::Reads,|artifact|{assert_eq!(artifact.text(),text);Ok(())}).unwrap();let foreign=QueryDb::default();assert!(foreign.with_generator_fixture(&capture,GeneratorName::Reads,|_|Ok(())).is_err());
}
const DERIVED_CODE:&str="#define PUBLISHED_BY(T,V,K)\n/datum/probe\n    var/value\n    var/derived\n/datum/probe/draw()\n    return helper()\n/datum/probe/helper()\n    return value\n/datum/probe/child/helper()\n    return derived\n/datum/probe/derive_derived()\n    return value\n/mob/probe\n    var/health\n/mob/probe/life_hud()\n    return health\n/mob/probe/reactions()\n    . += every(1, members=/datum/probe)\n    . += on_cross()\n    . += on_notice()\nPUBLISHED_BY(/mob/probe,health,HEALTH_KEY)\n";
#[test]fn actual_derived_reads_kind11_is_checked_multifile_raw_output_and_never_demands_kind4(){let fixture=Fixture::new(DERIVED_CODE,false);let capture=fixture.capture();let before=fixture.reads.load(Ordering::Relaxed);assert!(fixture.db.with_generator_fixture(&capture,GeneratorName::DerivedReads,|_|Ok(())).is_err(),"single consumer cannot reinterpret old multifile role");assert_eq!(fixture.db.db.stats(dm_query::Kind(11)).computed,0);let(pointer,text)=fixture.db.with_generator_files_fixture(&capture,GeneratorName::DerivedReads,|artifact|{assert_eq!(artifact.name(),"derived_reads");assert!(artifact.diagnostics().is_empty());assert_eq!(artifact.files().len(),1);let(path,text)=&artifact.files()[0];assert_eq!(path,"code/_generated/reads.dm");assert!(text.contains("/datum/probe/child/generated_reads()"));assert!(text.contains("HEALTH_KEY"));assert!(text.contains("RXB_CROSS | RXB_EVERY | RXB_NOTICE"));Ok((text.as_ptr()as usize,text.clone()))}).unwrap();let computed=fixture.db.db.stats(dm_query::Kind(11)).computed;fixture.db.with_generator_files_fixture(&capture,GeneratorName::DerivedReads,|artifact|{assert_eq!(artifact.files()[0].1.as_ptr()as usize,pointer);assert_eq!(artifact.files()[0].1,text);Ok(())}).unwrap();assert_eq!(fixture.db.db.stats(dm_query::Kind(11)).computed,computed);assert_eq!(fixture.db.db.stats(crate::query_db::body_syntax::BODY_SYNTAX).computed,0);assert_eq!(fixture.db.db.stats(REACTIVE_RESULT).computed,0);assert_eq!(fixture.reads.load(Ordering::Relaxed),before);let foreign=QueryDb::default();assert!(foreign.with_generator_files_fixture(&capture,GeneratorName::DerivedReads,|_|Ok(())).is_err());}
